attribute vec3 aO; attribute float aT, aK; attribute vec4 aD; uniform float uTime; varying vec2 vP; varying float vU, vK, vR;
    void main(){ float u = uTime - aT; if (u < 0. || u > 3.10){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK; vR = aD.x;
      if (aK < 1.5 || aK > 6.5){ float S = aD.x + .3; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.); }
      else { vec4 mv = viewMatrix*vec4(aO + vec3(0., .95, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.1; float S = 1.1; mv.xy += position.xy*vec2(S*.85, S*1.05); vP = position.xy; gl_Position = projectionMatrix*mv; }
    }

